SET NOCOUNT ON;
IF DB_NAME()<>N'EnglishCenter_DEMO_LOCAL' THROW 51910,'Wrong demo catalog',1;
IF (SELECT COUNT(*) FROM dbo.Account)<>67 OR (SELECT COUNT(*) FROM dbo.StudentProfile)<>50 OR
 (SELECT COUNT(*) FROM dbo.Course)<>6 OR (SELECT COUNT(*) FROM dbo.Band)<>5 OR
 (SELECT COUNT(*) FROM dbo.TrainingProgram)<>12 OR (SELECT COUNT(*) FROM dbo.Class)<>12 OR
 (SELECT COUNT(*) FROM dbo.EntryTestSession)<>12 OR (SELECT COUNT(*) FROM dbo.Registration)<>70
 THROW 51910,'Demo counts mismatch',1;
IF EXISTS(SELECT 1 FROM dbo.Account WHERE email NOT LIKE '%@demo.example') THROW 51911,'Non-demo identity',1;
IF EXISTS(SELECT 1 FROM dbo.StudentProfile p JOIN dbo.Account a ON a.account_id=p.account_id WHERE a.phone IS NULL OR a.phone NOT LIKE '0[35789]________' OR DATALENGTH(a.phone)<>10) THROW 51911,'Student contact contract mismatch',1;
IF EXISTS(SELECT 1 FROM dbo.Account WHERE must_change_password=1) THROW 51911,'Staff password walkthrough incomplete',1;
IF EXISTS(SELECT 1 FROM dbo.Registration r CROSS APPLY dbo.ufn_RegistrationUnfinished(r.registration_id) f WHERE r.is_unfinished<>f.isUnfinished) THROW 51912,'Unfinished projection mismatch',1;
IF EXISTS(SELECT 1 FROM dbo.Invoice i LEFT JOIN dbo.Payment p ON i.invoice_id=p.invoice_id WHERE (i.status='PAID' AND (p.payment_id IS NULL OR p.amount_paid<>i.amount)) OR (i.status<>'PAID' AND p.payment_id IS NOT NULL)) THROW 51912,'Invoice payment mismatch',1;
IF EXISTS(SELECT 1 FROM dbo.StudentClassAssignment a JOIN dbo.Registration r ON r.registration_id=a.registration_id JOIN dbo.Class c ON c.class_id=a.class_id JOIN dbo.TrainingProgram p ON p.program_id=c.program_id LEFT JOIN dbo.BandAssignment b ON b.registration_id=r.registration_id LEFT JOIN dbo.Invoice i ON i.registration_id=r.registration_id WHERE r.status<>'ADMITTED' OR i.status<>'PAID' OR i.invoice_id IS NULL OR r.course_id<>p.course_id OR b.band_id<>p.band_id OR b.band_assignment_id IS NULL) THROW 51912,'Placement eligibility mismatch',1;
IF EXISTS(SELECT 1 FROM dbo.BandAssignment b JOIN dbo.EntryTestAttempt a ON a.attempt_id=b.best_attempt_id WHERE a.score<>(SELECT MAX(x.score) FROM dbo.EntryTestAttempt x WHERE x.registration_id=b.registration_id) OR b.band_id<>(SELECT TOP(1) band_id FROM dbo.Band WHERE min_score<=a.score ORDER BY min_score DESC)) THROW 51912,'Best score or band mismatch',1;
IF EXISTS(SELECT 1 FROM dbo.EntryTestAttempt a JOIN dbo.EntryTestBooking b ON b.booking_id=a.completed_booking_id JOIN dbo.EntryTestSession s ON s.session_id=b.session_id WHERE a.graded_at<s.end_at OR a.graded_by<>s.grader_id OR b.booked_at>=s.start_at) THROW 51912,'Entry result chronology mismatch',1;
IF EXISTS(SELECT 1 FROM dbo.BandAssignment b JOIN dbo.EntryTestAttempt a ON a.attempt_id=b.best_attempt_id JOIN dbo.Registration r ON r.registration_id=b.registration_id WHERE b.assigned_at<a.graded_at OR r.admission_confirmed_at<b.assigned_at OR r.admission_approved_at<r.admission_confirmed_at) THROW 51912,'Admission chronology mismatch',1;
IF EXISTS(SELECT 1 FROM dbo.TrainingProgram p LEFT JOIN dbo.ScoreComponentConfig c ON c.program_id=p.program_id GROUP BY p.program_id HAVING SUM(c.weight)<>100 OR SUM(CASE WHEN c.kind='FINAL_EXAM' THEN 1 ELSE 0 END)<>1) THROW 51912,'Program weights mismatch',1;
IF EXISTS(SELECT 1 FROM dbo.GradeReport g CROSS APPLY dbo.ufn_GradeTotal(g.class_assignment_id) t WHERE g.status IN ('SUBMITTED','FINALIZED') AND t.isComplete=0 OR g.status='FINALIZED' AND g.final_score<>t.total) THROW 51912,'Grade total mismatch',1;
IF EXISTS(SELECT 1 FROM dbo.StudentClassAssignment a WHERE NOT EXISTS(SELECT 1 FROM dbo.GradeReport g WHERE g.class_assignment_id=a.class_assignment_id)) THROW 51912,'Placement draft report missing',1;
IF EXISTS(SELECT 1 FROM dbo.Class c CROSS APPLY dbo.ufn_ClassObligationProgress(c.class_id) p WHERE c.status='COMPLETED' AND (p.expectedLessonCount<>p.heldLessonCount OR p.currentFinalExamCount<>1 OR p.heldFinalExamCount<>1)) THROW 51912,'Completed obligations mismatch',1;
IF EXISTS(SELECT 1 FROM dbo.Class c JOIN dbo.StudentClassAssignment a ON a.class_id=c.class_id GROUP BY c.class_id,c.max_size HAVING COUNT(*)>c.max_size) THROW 51912,'Class capacity exceeded',1;
IF EXISTS(SELECT 1 FROM dbo.EntryTestSession s JOIN dbo.EntryTestBooking b ON b.session_id=s.session_id AND b.status='SCHEDULED' GROUP BY s.session_id,s.capacity HAVING COUNT(*)>s.capacity) THROW 51912,'Test capacity exceeded',1;
IF EXISTS(SELECT 1 FROM dbo.Schedule s JOIN dbo.Schedule t ON s.schedule_id<t.schedule_id AND s.is_current=1 AND t.is_current=1 AND s.session_date=t.session_date AND s.start_time<t.end_time AND t.start_time<s.end_time JOIN dbo.Class c ON c.class_id=s.class_id JOIN dbo.Class d ON d.class_id=t.class_id WHERE c.status<>'CANCELLED' AND d.status<>'CANCELLED' AND (s.room=t.room OR c.teacher_id=d.teacher_id)) THROW 51912,'Teacher or room schedule conflict',1;
IF EXISTS(SELECT 1 FROM sys.check_constraints WHERE is_disabled=1 OR is_not_trusted=1) OR EXISTS(SELECT 1 FROM sys.foreign_keys WHERE is_disabled=1 OR is_not_trusted=1) THROW 51912,'Disabled or untrusted constraint',1;
SELECT 'PASS' AS validation, (SELECT COUNT(*) FROM dbo.Account) AS accounts,(SELECT COUNT(*) FROM dbo.Registration) AS registrations,(SELECT COUNT(*) FROM dbo.Invoice) AS invoices,(SELECT COUNT(*) FROM dbo.Payment) AS payments,(SELECT COUNT(*) FROM dbo.Attendance) AS attendance,(SELECT COUNT(*) FROM dbo.Score) AS scores,(SELECT COUNT(*) FROM dbo.GradeReport) AS gradeReports,(SELECT COUNT(*) FROM dbo.AuditLog) AS realAuditEvents,(SELECT COUNT(*) FROM dbo.__EFMigrationsHistory) AS migrations;
